"""The angel at the pearl gate (Rev 21:12) from art/raw/gate_angel_03.png (generated by art/gen_gate_angel.py).
The generator painted a jasper pillar on each side; they are cut away row by row outside the wings' outline.
Writes game/art/people/gate_angel.png in the people layout (cols idle, wing lift, idle, wing lift; rows down/up/left all
the front view: the angel always faces those who come to the gate) and out/gate_angel_3x.png. Angels may have
wings (they are not redeemed humans); no halo."""
import sys
import numpy as np
from PIL import Image
sys.path.insert(0, 'art')
from common import quant, keep_main, OUTL

EDGE = 16                                    # the pillars lie within 16 px of each side


def cut_pillars(a):
    out = a.copy()
    for y in range(a.shape[0]):
        row = [tuple(a[y, x, :3]) if a[y, x, 3] else None for x in range(a.shape[1])]
        left = [x for x in range(EDGE) if row[x] == OUTL]
        right = [x for x in range(a.shape[1] - EDGE, a.shape[1]) if row[x] == OUTL]
        out[y, :left[0] if left else EDGE, 3] = 0
        out[y, (right[-1] + 1) if right else a.shape[1] - EDGE:, 3] = 0
    return out


def lift(a):
    """Second frame: the wings (outside the body's columns) rise one pixel, a calm breath."""
    b = a.copy(); body = slice(22, 42)
    for x in list(range(0, 22)) + list(range(42, a.shape[1])):
        b[:-1, x] = a[1:, x]; b[-1, x] = 0
    b[:, body] = a[:, body]
    return b


def main():
    a = np.array(quant(Image.open('art/raw/gate_angel_03.png')))
    a = np.array(keep_main(Image.fromarray(cut_pillars(a)), 0.3))
    ys, xs = np.nonzero(a[..., 3])
    a = a[:ys.max() + 1]                                        # feet on the bottom row
    pad = np.zeros((64, 64, 4), np.uint8); pad[64 - a.shape[0]:] = a
    pair = np.concatenate([pad, lift(pad)], 1)
    row = np.concatenate([pair, pair], 1)
    Image.fromarray(np.concatenate([row, row, row], 0)).save('game/art/people/gate_angel.png')
    big = Image.fromarray(pair).resize((128 * 3, 64 * 3), Image.NEAREST)
    bg = Image.new('RGBA', big.size, (70, 62, 84, 255)); bg.alpha_composite(big); bg.save('out/gate_angel_3x.png')
    print('gate angel ok')


if __name__ == '__main__':
    main()
